insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigação da família, da comunidade, da sociedade e do poder público assegurar à pessoa idosa, com absoluta prioridade, a efetivação dos direitos à vida, saúde, alimentação, educação, cultura, esporte, lazer, trabalho, cidadania, liberdade, dignidade, respeito e convivência familiar e comunitária. A prioridade compreende atendimento preferencial imediato e individualizado; preferência na formulação e execução de políticas sociais; destinação privilegiada de recursos públicos; formas alternativas de participação e convívio com as demais gerações; priorização do atendimento pela própria família, em detrimento do asilar, exceto para quem não a possua ou careça de condições; capacitação de recursos humanos em geriatria e gerontologia; divulgação de informações educativas sobre o envelhecimento; e acesso à rede de saúde e assistência social.', '["Obrigação da família, da comunidade, da sociedade e do poder público.","Absoluta prioridade.","Atendimento preferencial imediato e individualizado.","Preferência pelo atendimento familiar, e não asilar."]'::jsonb, '["A prioridade é ABSOLUTA.","Atendimento pela família tem preferência sobre o asilar."]'::jsonb, 'A pessoa idosa tem atendimento preferencial imediato em repartições públicas e privadas.', '["Assertiva que atribui o dever de proteger a pessoa idosa apenas ao Estado erra: é também da família, da comunidade e da sociedade."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
