insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigação do Estado e da sociedade assegurar à pessoa idosa a liberdade, o respeito e a dignidade como pessoa humana e sujeito de direitos civis, políticos, individuais e sociais. A liberdade compreende ir, vir e estar nos logradouros públicos, opinião e expressão, crença e culto religioso, prática de esportes e diversões, participação na vida familiar e comunitária, participação na vida política e buscar refúgio, auxílio e orientação. O respeito consiste na inviolabilidade da integridade física, psíquica e moral, abrangendo imagem, identidade, autonomia, valores, ideias e crenças, espaços e objetos pessoais. É dever de todos zelar pela dignidade da pessoa idosa, colocando-a a salvo de tratamento desumano, violento, aterrorizante, vexatório ou constrangedor.', '["Liberdade: ir e vir, opinião, crença, esportes, vida familiar e política.","Respeito: integridade física, psíquica e moral.","Dever de todos de zelar pela dignidade."]'::jsonb, '["Liberdade inclui a participação na vida política.","Respeito abrange imagem, identidade, autonomia e objetos pessoais."]'::jsonb, 'A pessoa idosa pode professar sua religião e participar da vida comunitária.', '["Assertiva que restringe a liberdade da pessoa idosa ao ir e vir erra: abrange também opinião, crença e participação política."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
