insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os benefícios de aposentadoria e pensão do Regime Geral da Previdência Social observarão, na concessão, critérios de cálculo que preservem o valor real dos salários sobre os quais incidiu contribuição. Os valores dos benefícios em manutenção serão reajustados na mesma data de reajuste do salário-mínimo, pro rata, conforme as datas de início ou do último reajustamento, com base em percentual definido em regulamento, observados os critérios da Lei nº 8.213, de 24 de julho de 1991.', '["Preservação do valor real dos salários de contribuição.","Reajuste na data do salário-mínimo, pro rata."]'::jsonb, '["ATUALIZAÇÃO: as regras de reajuste previdenciário foram alteradas por leis posteriores."]'::jsonb, 'O benefício é reajustado na mesma época do salário-mínimo.', '["Assertiva que reajusta os benefícios em data distinta do salário-mínimo erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-29'
