select u.id, u.content_sha256, 'O pagamento de parcelas relativas a benefícios, efetuado com atraso por responsabilidade da Previdência Social, será atualizado pelo mesmo índice utilizado para os reajustamentos dos benefícios do Regime Geral de Previdência Social, verificado no período entre o mês que deveria ter sido pago e o mês do efetivo pagamento.', '["Atualização das parcelas atrasadas pelo índice de reajuste dos benefícios."]'::jsonb, '["Atraso por culpa da Previdência."]'::jsonb, 'Parcelas pagas com atraso pelo INSS são atualizadas monetariamente.', '["Assertiva que dispensa atualização das parcelas atrasadas por culpa da Previdência erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
