select u.id, u.content_sha256, 'A assistência social às pessoas idosas será prestada de forma articulada, conforme os princípios e diretrizes da Lei Orgânica da Assistência Social, da Política Nacional da Pessoa Idosa, do SUS e das demais normas pertinentes.', '["Assistência social articulada com LOAS, Política Nacional da Pessoa Idosa e SUS."]'::jsonb, '["Atuação articulada."]'::jsonb, 'A assistência social e a saúde atuam de forma coordenada.', '["Assertiva que isola a assistência social das demais políticas erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
