insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Às pessoas idosas, a partir de 65 anos, que não possuam meios para prover sua subsistência, nem de tê-la provida por sua família, é assegurado o benefício mensal de 1 salário mínimo, nos termos da Loas. O benefício já concedido a qualquer membro da família não será computado no cálculo da renda familiar per capita da Loas.', '["Benefício de prestação continuada: 1 salário mínimo.","Idade mínima de 65 anos.","Não computa o benefício de outro membro da família na renda per capita."]'::jsonb, '["Idade do BPC: 65 anos, e não 60.","Benefício de outro idoso da família NÃO conta na renda per capita."]'::jsonb, 'A pessoa idosa de 66 anos sem renda pode receber um salário mínimo do BPC.', '["Assertiva que concede o BPC a partir de 60 anos erra: são 65 anos."]'::jsonb, '[{"termo":"BPC","significado":"Benefício de Prestação Continuada, da assistência social."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-34'
