insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todas as entidades de longa permanência, ou casa-lar, são obrigadas a firmar contrato de prestação de serviços com a pessoa idosa abrigada. Nas entidades filantrópicas ou casas-lares é facultada a cobrança de participação da pessoa idosa no custeio, que não poderá exceder 70% de qualquer benefício previdenciário ou de assistência social percebido, forma estabelecida pelo Conselho Municipal da Pessoa Idosa ou da Assistência Social. Se a pessoa idosa for incapaz, o contrato será firmado por seu representante legal.', '["Contrato obrigatório com a pessoa abrigada.","Participação no custeio limitada a 70% do benefício.","Representante legal assina se a pessoa for incapaz."]'::jsonb, '["Teto de 70% do benefício."]'::jsonb, 'A entidade filantrópica cobra, no máximo, 70% da aposentadoria da pessoa abrigada.', '["Assertiva que fixa em 100% do benefício o limite da cobrança erra: é de 70%."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
