select u.id, u.content_sha256, 'O acolhimento de pessoas idosas em situação de risco social, por adulto ou núcleo familiar, caracteriza a dependência econômica, para os efeitos legais.', '["Acolhimento caracteriza dependência econômica."]'::jsonb, '["Vigência a partir de 1º de janeiro de 2004 (art. 118)."]'::jsonb, 'Quem acolhe uma pessoa idosa em risco social tem a dependência econômica reconhecida para fins legais.', '["Assertiva que nega efeitos legais ao acolhimento de pessoa idosa erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa idosa tem direito a moradia digna, no seio da família natural ou substituta, ou desacompanhada de seus familiares, quando assim o desejar, ou em instituição pública ou privada. A assistência integral em entidade de longa permanência será prestada quando verificada inexistência de grupo familiar, casa-lar, abandono ou carência de recursos. Toda instituição fica obrigada a manter identificação externa visível, sob pena de interdição. As instituições devem manter padrões de habitação compatíveis, alimentação regular e higiene.', '["Moradia digna em família, sozinha ou em instituição.","Entidade de longa permanência é subsidiária.","Identificação externa visível, sob pena de interdição."]'::jsonb, '["Institucionalização é subsidiária."]'::jsonb, 'A pessoa idosa pode morar sozinha, se assim o desejar.', '["Assertiva que obriga a internação em instituição de pessoa idosa que quer morar sozinha erra."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-37'
