insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos programas habitacionais, públicos ou subsidiados com recursos públicos, a pessoa idosa goza de prioridade na aquisição de imóvel para moradia própria, observada a reserva de pelo menos 3% das unidades residenciais; a implantação de equipamentos urbanos comunitários; a eliminação de barreiras arquitetônicas; e critérios de financiamento compatíveis com aposentadoria e pensão. As unidades reservadas devem situar-se preferencialmente no pavimento térreo.', '["Reserva de pelo menos 3% das unidades.","Eliminação de barreiras.","Financiamento compatível com a aposentadoria.","Preferência por pavimento térreo."]'::jsonb, '["Reserva mínima de 3%."]'::jsonb, 'Em um conjunto habitacional público, 3% das unidades são para pessoas idosas.', '["Assertiva que fixa em 10% a reserva de unidades erra: é de pelo menos 3%."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-38'
