insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de atendimento são responsáveis pela manutenção das próprias unidades, observadas as normas de planejamento e execução da Política Nacional da Pessoa Idosa. As entidades governamentais e não governamentais ficam sujeitas à inscrição de seus programas perante a Vigilância Sanitária e o Conselho Municipal da Pessoa Idosa (ou Estadual ou Nacional, na falta), especificando os regimes de atendimento, com instalações adequadas de habitabilidade, higiene, salubridade e segurança; objetivos estatutários e plano de trabalho compatíveis; regular constituição; e idoneidade dos dirigentes.', '["Responsabilidade pela manutenção das unidades.","Inscrição dos programas na Vigilância Sanitária e no Conselho.","Requisitos: instalações, estatuto, constituição regular e idoneidade."]'::jsonb, '["Inscrição OBRIGATÓRIA dos programas."]'::jsonb, 'A casa de repouso inscreve seu programa no Conselho Municipal da Pessoa Idosa.', '["Assertiva que dispensa a inscrição dos programas das entidades erra."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-48'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de institucionalização de longa permanência adotarão os princípios da preservação dos vínculos familiares; atendimento personalizado e em pequenos grupos; manutenção da pessoa idosa na mesma instituição, salvo força maior; participação nas atividades comunitárias; observância dos direitos e garantias; e preservação da identidade, com ambiente de respeito e dignidade. O dirigente responderá civil e criminalmente pelos atos que praticar em detrimento da pessoa idosa, sem prejuízo das sanções administrativas.', '["Preservação dos vínculos familiares.","Atendimento personalizado em pequenos grupos.","Manutenção na mesma instituição.","Responsabilidade civil e criminal do dirigente."]'::jsonb, '["Dirigente responde civil e criminalmente."]'::jsonb, 'O dirigente que maltrata os abrigados responde civil e criminalmente.', '["Assertiva que isenta o dirigente da entidade de responsabilidade criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-49'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem obrigações das entidades de atendimento: celebrar contrato escrito de prestação de serviço, especificando o atendimento, as obrigações e os preços; observar os direitos e garantias; fornecer vestuário adequado, se pública, e alimentação suficiente; oferecer instalações adequadas e atendimento personalizado; diligenciar a preservação dos vínculos familiares; oferecer acomodações para visitas; proporcionar cuidados à saúde; promover atividades educacionais, esportivas, culturais e de lazer; propiciar assistência religiosa; proceder a estudo social e pessoal; comunicar doenças infectocontagiosas; providenciar documentos de cidadania; fornecer comprovante de depósito dos bens móveis; e manter arquivo de anotações.', '["Contrato escrito.","Vestuário (se pública) e alimentação suficiente.","Cuidados à saúde e atividades de lazer.","Assistência religiosa.","Comprovante de depósito dos bens móveis."]'::jsonb, '["Vestuário adequado só se a entidade for PÚBLICA."]'::jsonb, 'A entidade entrega ao abrigado comprovante dos bens móveis que guarda.', '["Assertiva que dispensa o contrato escrito com a pessoa abrigada erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
