insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 7º da Lei da Política Nacional do Idoso passa a prever que compete aos Conselhos a supervisão, o acompanhamento, a fiscalização e a avaliação da política nacional do idoso, no âmbito de suas instâncias político-administrativas.', '["Altera o art. 7º da Lei nº 8.842, de 1994.","Conselhos supervisionam e avaliam a política."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 8.842, de 1994."]'::jsonb, 'O Conselho avalia a política de atendimento do Município.', '["Assertiva que retira dos Conselhos o poder de fiscalizar a política erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
