select u.id, u.content_sha256, 'Deixar o profissional de saúde ou o responsável por estabelecimento de saúde ou instituição de longa permanência de comunicar à autoridade competente os casos de crimes contra pessoa idosa de que tiver conhecimento: multa de R$ 500,00 a R$ 3.000,00, aplicada em dobro no caso de reincidência.', '["Omissão de comunicação de crimes pela saúde ou instituição.","Multa de R$ 500,00 a R$ 3.000,00.","Dobro na reincidência."]'::jsonb, '["Infração administrativa (multa), com dobro na reincidência."]'::jsonb, 'O médico que não comunica maus-tratos que presenciou é multado.', '["Assertiva que prevê prisão ao profissional de saúde omisso erra: a sanção é multa."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
