insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se, subsidiariamente, ao procedimento administrativo as disposições das Leis nºs 6.437, de 20 de agosto de 1977, e 9.784, de 29 de janeiro de 1999.', '["Aplicação subsidiária da lei de infrações sanitárias e da lei do processo administrativo federal."]'::jsonb, '["Subsidiariedade."]'::jsonb, 'Na falta de regra, aplica-se a lei do processo administrativo.', '["Assertiva que afasta qualquer lei subsidiária do procedimento administrativo erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
