insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurada prioridade na tramitação dos processos e procedimentos e na execução dos atos e diligências judiciais em que figure como parte ou interveniente pessoa com idade igual ou superior a 60 anos, em qualquer instância. O interessado prova a idade e requer o benefício, anotando-se a circunstância nos autos. A prioridade não cessa com a morte, estendendo-se ao cônjuge supérstite ou companheiro maior de 60 anos. Estende-se aos processos na Administração Pública, empresas de serviços públicos, instituições financeiras e Defensoria. Será garantido fácil acesso aos assentos e caixas. Dentre os processos de pessoas idosas, dar-se-á prioridade especial aos das maiores de 80 anos.', '["Prioridade a partir de 60 anos, em qualquer instância.","Estende-se ao cônjuge ou companheiro supérstite maior de 60 anos.","Alcança a Administração, serviços públicos e bancos.","Prioridade especial para maiores de 80 anos."]'::jsonb, '["Prioridade ESPECIAL a partir de 80 anos.","A prioridade se estende ao cônjuge sobrevivente maior de 60 anos."]'::jsonb, 'O processo de uma pessoa de 82 anos tem prioridade especial.', '["Assertiva que extingue a prioridade com a morte da pessoa idosa erra: ela se estende ao cônjuge ou companheiro."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
