insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Ministério Público instaurar o inquérito civil e a ação civil pública para proteção dos direitos difusos, coletivos, individuais indisponíveis e individuais homogêneos da pessoa idosa; promover e acompanhar as ações de alimentos, de interdição e de designação de curador especial e oficiar em todos os feitos em que se discutam direitos de pessoas idosas em risco; atuar como substituto processual da pessoa idosa em risco; promover a revogação de procuração em situações de risco; instaurar procedimento administrativo com notificações, depoimentos, condução coercitiva, requisição de informações, exames, perícias e documentos; e instaurar sindicâncias e requisitar diligências investigatórias.', '["Inquérito civil e ação civil pública.","Ações de alimentos, interdição e curador especial.","Substituição processual da pessoa idosa em risco.","Revogação de procuração.","Procedimento administrativo com poderes de requisição."]'::jsonb, '["O MP atua como SUBSTITUTO PROCESSUAL da pessoa idosa em risco."]'::jsonb, 'O Promotor ajuíza ação de alimentos em favor de pessoa idosa em risco.', '["Assertiva que impede o MP de atuar como substituto processual da pessoa idosa erra."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
